// Helper functions
export function getToolsByCategory(categorySlug: string): Tool[] {
  return tools.filter((t) => t.category === categorySlug);
}

export function getToolByRoute(category: string, slug: string): Tool | undefined {
  return tools.find((t) => t.category === category && t.slug === slug);
}

export function getToolByPath(routePrefix: string, slug: string): Tool | undefined {
  const route = `${routePrefix}/${slug}`;
  return tools.find((t) => t.route === route);
}

export function getPopularTools(): Tool[] {
  return tools.filter((t) => t.popular);
}

export function getFeaturedTools(): Tool[] {
  return tools.filter((t) => t.featured);
}

export function searchTools(query: string): Tool[] {
  const q = query.toLowerCase();
  return tools.filter(
    (t) =>
      t.name.toLowerCase().includes(q) ||
      t.description.toLowerCase().includes(q) ||
      t.category.toLowerCase().includes(q)
  );
}
